'use client';

import * as React from 'react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { LayoutDashboard, MessageSquare, UserCog, LogOut, Settings } from 'lucide-react';
import { cn } from '@/lib/utils';
import { useAuthStore } from '@/store/useAuthStore';
import { Button } from '@/components/Button';

const navItems = [
    { href: '/', label: 'Overview', icon: LayoutDashboard },
    { href: '/dashboard/chats', label: 'Conversations', icon: MessageSquare },
    { href: '/profile', label: 'Settings', icon: Settings },
];

export function Sidebar({ isOpen, onClose }: { isOpen?: boolean; onClose?: () => void }) {
    const pathname = usePathname();
    const router = useRouter();
    const logout = useAuthStore(state => state.logout);

    const handleLogout = () => {
        logout();
        router.push('/auth/login');
    };

    return (
        <>
            {/* Mobile Overlay */}
            {isOpen && (
                <div
                    className="fixed inset-0 bg-background/80 backdrop-blur-sm z-40 lg:hidden"
                    onClick={onClose}
                />
            )}

            <aside
                className={cn(
                    "fixed inset-y-0 left-0 w-64 border-r bg-card p-6 flex flex-col z-50 transition-transform duration-300 lg:translate-x-0",
                    isOpen ? "translate-x-0" : "-translate-x-full"
                )}
            >
                <div className="flex items-center gap-3 px-2 mb-10">
                    <div className="h-10 w-10 rounded-xl bg-primary flex items-center justify-center shadow-lg shadow-primary/30">
                        <span className="text-primary-foreground font-extrabold text-xl">A</span>
                    </div>
                    <div className="flex flex-col">
                        <span className="text-lg font-bold tracking-tight leading-none">Antigravity</span>
                        <span className="text-[10px] text-muted-foreground font-medium uppercase tracking-wider mt-1">AI Solutions</span>
                    </div>
                </div>

                <nav className="space-y-1.5 flex-1">
                    {navItems.map((item) => {
                        const Icon = item.icon;
                        const isActive = pathname === item.href || (item.href !== '/' && pathname.startsWith(item.href));

                        return (
                            <Link
                                key={item.href}
                                href={item.href}
                                onClick={onClose}
                                className={cn(
                                    'flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-medium transition-all duration-200 group relative overflow-hidden',
                                    isActive
                                        ? 'text-primary'
                                        : 'text-muted-foreground hover:bg-muted/50 hover:text-foreground'
                                )}
                            >
                                {isActive && (
                                    <div className="absolute inset-0 bg-primary/10 transition-opacity" />
                                )}
                                <Icon className={cn("h-5 w-5 relative z-10", isActive ? "text-primary" : "text-muted-foreground group-hover:text-foreground")} />
                                <span className="relative z-10">{item.label}</span>
                                {isActive && (
                                    <div className="absolute right-0 top-1/2 -translate-y-1/2 h-6 w-1 rounded-l-full bg-primary" />
                                )}
                            </Link>
                        );
                    })}
                </nav>

                <div className="pt-6 border-t mt-auto">
                    <Button
                        variant="ghost"
                        onClick={handleLogout}
                        className="w-full justify-start gap-3 rounded-xl text-muted-foreground hover:text-destructive hover:bg-destructive/10 h-12"
                    >
                        <LogOut className="h-5 w-5" />
                        Sign Out
                    </Button>
                </div>
            </aside>
        </>
    );
}

